"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9851],{57700:e=>{e.exports=JSON.parse('{"functions":[{"name":"playerAdded","desc":"Runs the full join sequence for one player: ready-watcher setup, leaderstat\\ndefaults, profile load (kicking on failure), [PlayerService.PlayerLoaded],\\nthe biome wait, the initial character spawn, the READY handshake with its\\n`LOAD_TIMEOUT` kick, real leaderstat values, and the `PLAYER_JOINED`\\nbroadcast.\\n\\nYields for as long as the handshake takes, so it is spawned per player\\nrather than called inline.","params":[{"name":"player","desc":"the joining player","lua_type":"Player"}],"returns":[],"function_type":"static","private":true,"source":{"line":108,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"spawnCharacter","desc":"Builds and places a character at `origin`.\\n\\nThe model comes from [Character.createModel]. It is spawned anchored and\\nlifted 2.4 studs so it cannot fall through terrain that is still settling,\\nassigned the player collision group, and unanchored 0.2s later once it is\\nconfirmed parented to the Workspace. Any previous character is destroyed\\nfirst.","params":[{"name":"player","desc":"character owner","lua_type":"Player"},{"name":"origin","desc":"where to place the character","lua_type":"CFrame"}],"returns":[{"desc":"the new character, or nil when the model could not be built","lua_type":"Model?"}],"function_type":"static","private":true,"source":{"line":223,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"getPlayers","desc":"Returns a copy of the fully-loaded player list \u2014 players whose profile\\nloaded successfully, which is a strict subset of `Players:GetPlayers()`\\nduring the join window.","params":[],"returns":[{"desc":"","lua_type":"{ Player }"}],"function_type":"static","source":{"line":267,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"setWalkSpeed","desc":"Sets the player\'s walk speed, writing it both to the `BaseWalkSpeed`\\nattribute (which survives respawns and is what other systems read) and to\\nthe current humanoid, if any.","params":[{"name":"player","desc":"target","lua_type":"Player"},{"name":"speed","desc":"studs per second","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":282,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"getPlayerState","desc":"Returns the player\'s scratch state, lazily creating it on first access.\\n\\nThe wrapper closes over a [PlayerState] instance, so `getState` / `setState`\\ntake no player argument. The entry is dropped when the player leaves.","params":[{"name":"player","desc":"state owner","lua_type":"Player"}],"returns":[{"desc":"nil when the player has already left","lua_type":"PlayerStateData?"}],"function_type":"static","source":{"line":322,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"initPlayer","desc":"Spawns the player\'s first character and installs the per-character init and\\nrespawn behaviour for every subsequent one.\\n\\nOn each `CharacterAdded`: clears `SpawnOverride`, waits out a\\nnot-yet-parented character, creates the overhead nameplate, applies\\n`DEFAULT_WALKSPEED` to both the humanoid and the `BaseWalkSpeed` attribute,\\nand disables the `StrafingNoPhysics` humanoid state.\\n\\nDeath is handled once per character: ragdoll the corpse into the game\\ncontainer (retained in-world when the character carries\\n`KeepRagdollInWorld`), wait `RESPAWN_TIME`, then respawn back at `origin`.\\nThe `SpawnOverride` attribute is re-checked at three points during that\\nwait, so a minigame can claim respawn control at any moment without racing\\nthis loop.","params":[{"name":"player","desc":"player to initialise","lua_type":"Player"},{"name":"origin","desc":"spawn point, reused for every respawn","lua_type":"CFrame"}],"returns":[{"desc":"the initial character","lua_type":"Model?"}],"function_type":"static","source":{"line":373,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"_gatherSpawns","desc":"Collects every instance tagged `GameData.SPAWN_TAG` into `spawns` and keeps\\nthe list live by subscribing to the tag\'s added and removed signals \u2014 so\\nstreamed-in or runtime-built maps contribute spawns without a rescan.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":446,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"init","desc":"Boots the service: gathers spawn points, then starts watching for players.\\nSet the module-local `DEBUG` to trace the boot sequence.","params":[],"returns":[],"function_type":"static","source":{"line":472,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"start","desc":"Lifecycle hook kept for symmetry with the other core services. Intentionally\\nempty \u2014 all setup happens in [PlayerService.init].","params":[],"returns":[],"function_type":"static","source":{"line":493,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"getRandomSpawnOrign","desc":"Picks a random gathered spawn point, falling back to the world origin when\\nthe map has no tagged spawns.\\n\\nNote the spelling \u2014 \\"Orign\\", not \\"Origin\\".","params":[],"returns":[{"desc":"","lua_type":"CFrame"}],"function_type":"static","source":{"line":506,"path":"src/Server/Features/Core/PlayerService.luau"}},{"name":"watchForPlayers","desc":"Binds the join and leave handlers, running the join sequence for anyone who\\narrived before this connected.\\n\\nOn leave: drops the player from the loaded list, flushes their final coin\\nand playtime totals to the leaderboards (coins forced, so a lower value\\nstill overwrites), clears their scratch state, fires\\n[PlayerService.PlayerRemoving] so other services can clean up **before** the\\nprofile is written, then saves and unloads the profile.\\n\\nAlso installs a `BindToClose` that saves every remaining player, so a server\\nshutdown does not drop the last session\'s data. Both save paths are gated on\\n`ProfileDB.canSaveToDataStore`.","params":[],"returns":[],"function_type":"static","source":{"line":533,"path":"src/Server/Features/Core/PlayerService.luau"}}],"properties":[],"types":[{"name":"PlayerStateData","desc":"A per-player scratch state wrapper. Purely in-memory and session-scoped \u2014\\nnothing here is persisted; use [ProfileService] for anything that must\\nsurvive a rejoin.","fields":[{"name":"getState","lua_type":"(key: string) -> any","desc":"read a value by dotted path"},{"name":"setState","lua_type":"(key: string, value: any) -> ()","desc":"write a value by dotted path"},{"name":"_state","lua_type":"State.State<any>","desc":"the underlying State object"}],"source":{"line":304,"path":"src/Server/Features/Core/PlayerService.luau"}}],"name":"PlayerService","desc":"Owns the player lifecycle: join, profile load, character spawn, respawn and\\nleave.\\n\\n## Join sequence\\n\\n`playerAdded` is the spine, and its ordering matters:\\n\\n1. Subscribe to `PlayerReady` **before** anything can fire it, so the ready\\n   signal cannot be missed.\\n2. Seed leaderstats with their defaults, then load the profile \u2014 a failed\\n   load kicks the player rather than letting them play against empty data.\\n3. Fire [PlayerService.PlayerLoaded], the signal other services should hang\\n   their per-player setup off.\\n4. Wait for `BiomeService.ready` so terrain exists before anyone stands on\\n   it, then spawn the character \u2014 deliberately before waiting for READY, so\\n   the client loads into an existing character.\\n5. Wait up to `LOAD_TIMEOUT` (30s) for the client to dispatch `READY`,\\n   kicking on timeout, then push real leaderstat values and broadcast\\n   `PLAYER_JOINED`.\\n\\n:::info BiomeService is stubbed\\n`Features.Biome` was not ported (TODO Layer 12), so the `BiomeService` used\\nhere is a local `{ ready = true }` stub. The chunk-generation wait in step 4\\ntherefore falls through immediately.\\n:::\\n\\n## Signals\\n\\nPrefer these over the `Players` equivalents \u2014 they fire with the profile\\nloaded and let listeners clean up before the profile is saved:\\n[PlayerService.PlayerLoaded], [PlayerService.PlayerRemoving] and\\n[PlayerService.PlayerReady].\\n\\n## Respawn\\n\\nDeath is handled per character in [PlayerService.initPlayer]: ragdoll the\\ncorpse, wait `RESPAWN_TIME` (2s), then respawn at the original origin. The\\n`SpawnOverride` player attribute suppresses this entirely, which is how\\nminigames take over spawning without racing this loop.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":48,"path":"src/Server/Features/Core/PlayerService.luau"}}')}}]);